body:
I think life is too short to fight Mesa private headers with windows.h order of precedence issue and hacky redefinitions like:
```cpp
// mesa/src/util/glheader.h

#if defined(_WIN32) && !defined(__CYGWIN__)
/* Prevent glheader.h from including <windows.h> by defining APIENTRY */
#pragma push_macro("APIENTRY")
#ifndef APIENTRY
#define APIENTRY GLAPIENTRY
#endif
#include "GL/gl.h"
#include "GL/glext.h"
#pragma pop_macro("APIENTRY")
#else /* !(defined(_WIN32) && !defined(__CYGWIN__)) */
#include "GL/gl.h"
#include "GL/glext.h"
#endif /* defined(_WIN32) && !defined(__CYGWIN__) */
```

So, can you confirm that #106413 solves the issue and doesn't introduce warnings?

We discussed about this very problem (thirdparty libraries clashing and such) at a core meeting and @hpvb came up with this solution. I think this applies to this issue.

```cpp
// main.cpp (Godot analogue)
#include <stdio.h>

// Include the external code into a namespace
namespace badns {
#include "bad.h"
};

struct something {
	void* something_else;
};

int bad() {
	printf("Also bad, but you know, good\n");
	return 0;
}

int main() {
	badns::something x; // The compiler knows that "something" is not "badns::something" and will warn.
	bad();
	badns::bad(&x);
}
```

```cpp
// bad.h (Foreign code)
extern "C" {
#include <stdio.h>
typedef struct {
	int l;
} something;

int bad(something* s);
}
```

```cpp
// bad.c 
#include "bad.h"

int bad(something *s) {
	printf("Baaaad %i\n", s->l);
	return 1;
}
```

```terminal
$ g++ main.cpp bad.c -o main
$ ./main 
Also bad, but you know, good
Baaaad 32765 <-- undefined value, free RNG!
```
